require 'aws-sdk-s3'

# Description: Sublayer::Action responsible for uploading files to AWS S3.
# This action enables storing files generated by AI workflows (such as images, documents, etc.) in S3.
#
# Requires: 'aws-sdk-s3' gem
# $ gem install aws-sdk-s3
# Or add `gem 'aws-sdk-s3'` to your Gemfile
#
# It is initialized with bucket_name, file_path, s3_key (destination path), and optional metadata.
# It returns the S3 object URL upon successful upload.
#
# Example usage: When you want to store AI-generated files in S3 for later access or distribution.
# Common use cases include storing DALL-E generated images or LLM-generated documents.

class S3UploadFileAction < Sublayer::Actions::Base
  def initialize(bucket_name:, file_path:, s3_key:, metadata: {}, region: nil)
    @bucket_name = bucket_name
    @file_path = file_path
    @s3_key = s3_key
    @metadata = metadata
    @region = region || ENV['AWS_REGION'] || 'us-east-1'
    
    validate_inputs
  end

  def call
    begin
      upload_file
    rescue Aws::S3::Errors::ServiceError => e
      error_message = "AWS S3 service error: #{e.message}"
      Sublayer.configuration.logger.log(:error, error_message)
      raise StandardError, error_message
    rescue StandardError => e
      error_message = "Error uploading file to S3: #{e.message}"
      Sublayer.configuration.logger.log(:error, error_message)
      raise e
    end
  end

  private

  def validate_inputs
    raise ArgumentError, 'Bucket name cannot be empty' if @bucket_name.to_s.strip.empty?
    raise ArgumentError, 'S3 key cannot be empty' if @s3_key.to_s.strip.empty?
    raise ArgumentError, 'File path cannot be empty' if @file_path.to_s.strip.empty?
    raise ArgumentError, 'File does not exist' unless File.exist?(@file_path)
  end

  def s3_client
    @s3_client ||= Aws::S3::Client.new(
      region: @region,
      credentials: Aws::Credentials.new(
        ENV['AWS_ACCESS_KEY_ID'],
        ENV['AWS_SECRET_ACCESS_KEY']
      )
    )
  end

  def upload_file
    # Read the file
    file = File.open(@file_path, 'rb')

    # Prepare upload parameters
    params = {
      bucket: @bucket_name,
      key: @s3_key,
      body: file,
      metadata: @metadata
    }

    # Upload the file
    s3_client.put_object(params)
    
    # Close the file
    file.close

    # Generate the object URL
    object_url = "https://#{@bucket_name}.s3.#{@region}.amazonaws.com/#{@s3_key}"
    
    Sublayer.configuration.logger.log(:info, "Successfully uploaded file to S3: #{object_url}")
    
    object_url
  end
end